<?php
namespace SenderSuite;

final class DatabaseFailure extends \RuntimeException { public function __construct() { parent::__construct('Application database operation failed.'); } }
final class Database {
    private $wpdb;private $schema;private $depth=0;
    public function __construct($wpdb,Schema $schema) { $this->wpdb=$wpdb;$this->schema=$schema; }
    public function schema() { return $this->schema; }
    public function execute($sql,array $args=array()) { $old=$this->wpdb->suppress_errors(true);try { $r=$this->wpdb->query($args?$this->wpdb->prepare($sql,$args):$sql); }finally { $this->wpdb->suppress_errors($old); }if ($r===false) { throw new DatabaseFailure(); }return $r; }
    public function rows($sql,array $args=array()) { $old=$this->wpdb->suppress_errors(true);try { $r=$this->wpdb->get_results($args?$this->wpdb->prepare($sql,$args):$sql,ARRAY_A);$error=$this->wpdb->last_error; }finally { $this->wpdb->suppress_errors($old); }if ($error || !is_array($r)) { throw new DatabaseFailure(); }return $r; }
    public function transaction(callable $work) { $level=$this->depth;$save='ss_save_'.$level;$this->execute($level?'SAVEPOINT '.$save:'START TRANSACTION');$this->depth++;try { $result=$work($this);$this->execute($level?'RELEASE SAVEPOINT '.$save:'COMMIT');return $result; }catch (\Throwable $e) { try { $this->execute($level?'ROLLBACK TO SAVEPOINT '.$save:'ROLLBACK'); }catch (\Throwable $ignored) {}throw $e; }finally { $this->depth--; } }
    private function where($table,array $where,array &$args) { if (!$where) { return '1=1'; }$parts=array();foreach ($where as $name=>$value) { $this->schema->column($table,$name);$q=Schema::identifier($name);if ($value===null) { $parts[]=$q.' IS NULL'; }else { if (!is_scalar($value)) { throw new \InvalidArgumentException('Invalid filter value.'); }$parts[]=$q.'=%s';$args[]=$value; } }return implode(' AND ',$parts); }
    private function encode($table,array $data) { foreach ($data as $key=>&$value) { $spec=$this->schema->column($table,$key);if ($value===null) { if (!$spec['nullable'] && !$spec['auto_increment']) { throw new \InvalidArgumentException('Null required value.'); }continue; }if ($spec['type']==='JSON') { $value=json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR); }elseif ($spec['type']==='Boolean') { if (!is_bool($value)) { throw new \InvalidArgumentException('Boolean required.'); }$value=$value?1:0; }elseif ($spec['type']==='Integer' && !is_int($value)) { throw new \InvalidArgumentException('Integer required.'); }elseif (!is_scalar($value)) { throw new \InvalidArgumentException('Invalid column value.'); } }unset($value);return $data; }
    public function decode($table,array $data) { foreach ($data as $key=>&$value) { if (strpos($key,'__ss_')===0) { unset($data[$key]);continue; }$spec=$this->schema->column($table,$key);if ($value===null) { continue; }switch ($spec['type']) { case 'Integer':$value=(int)$value;break;case 'Boolean':$value=(bool)$value;break;case 'Float':$value=(float)$value;break;case 'JSON':$value=json_decode($value,false,512,JSON_THROW_ON_ERROR);break; } }unset($value);return $data; }
    public function select($table,array $where=array(),$limit=100,$offset=0) { if (!is_int($limit) || $limit<1 || !is_int($offset) || $offset<0) { throw new \InvalidArgumentException('Invalid pagination.'); }$args=array();$sql='SELECT * FROM '.Schema::identifier($this->schema->table($table)).' WHERE '.$this->where($table,$where,$args).' LIMIT %d OFFSET %d';$args[]=$limit;$args[]=$offset;return array_map(function($r)use($table){return $this->decode($table,$r);},$this->rows($sql,$args)); }
    public function one($table,array $where) { $rows=$this->select($table,$where,1);return $rows?$rows[0]:null; }
    public function insert($table,array $data) { if (!$data) { throw new \InvalidArgumentException('Empty insert.'); }$data=$this->encode($table,$data);$names=array();$marks=array();$args=array();foreach ($data as $key=>$value) { $names[]=Schema::identifier($key);$marks[]=$value===null?'NULL':'%s';if ($value!==null) { $args[]=$value; } }$this->execute('INSERT INTO '.Schema::identifier($this->schema->table($table)).' ('.implode(',',$names).') VALUES ('.implode(',',$marks).')',$args);return (int)$this->wpdb->insert_id; }
    public function update($table,array $data,array $where) { if (!$where || !$data) { throw new \InvalidArgumentException('Bounded nonempty update required.'); }$data=$this->encode($table,$data);$args=array();$set=array();foreach ($data as $key=>$value) { $set[]=Schema::identifier($key).'='.($value===null?'NULL':'%s');if ($value!==null) { $args[]=$value; } }$clause=$this->where($table,$where,$args);return $this->execute('UPDATE '.Schema::identifier($this->schema->table($table)).' SET '.implode(',',$set).' WHERE '.$clause,$args); }
    public function delete($table,array $where) { if (!$where) { throw new \InvalidArgumentException('Bounded delete required.'); }$args=array();return $this->execute('DELETE FROM '.Schema::identifier($this->schema->table($table)).' WHERE '.$this->where($table,$where,$args),$args); }
}
